// Scanner: mode_larson_scanner, FX.cpp:1209
function larson(S, E) {
	if (S.len <= 1) return fbStatic(S);
	const speed = S.frametime * map(S.speed, 0, 255, 96, 2);
	const pixels = Math.trunc(S.len / speed);
	S.fade_out(255 - S.intensity);
	if (E.step > S.now) return; // pause
	let index = E.aux1 + pixels;
	if (pixels == 0) {
		const frames = Math.trunc(speed / S.len);
		const st = E.step;
		E.step = (st + 1) >>> 0;
		if (st < frames) return;
		E.step = 0;
		index++;
	}
	if (index > S.len) {
		E.aux0 = E.aux0 ? 0 : 1;
		E.aux1 = 0;
		if (E.aux0 || S.check2) E.step = (S.now + S.custom1 * 25) >>> 0;
		else E.step = 0;
	} else {
		for (let i = E.aux1; i < index; i++) {
			const j = E.aux0 ? i : S.len - 1 - i;
			const c = S.color_from_palette(j, true, S.PALETTE_SOLID_WRAP, 0);
			S.setPixelColor(j, c);
			if (S.check1) S.setPixelColor(S.len - 1 - j, S.col[2] ? S.col[2] : c);
		}
		E.aux1 = index & 0xFFFF;
	}
}
FXS.add("Scanner", larson);

