// Rain: mode_rain, FX.cpp:1330 (1D path)
FXS.add("Rain", function(S, E){
	if (S.len <= 1) return fbStatic(S);
	const width = S.len, height = 1;
	E.step = (E.step + S.frametime) >>> 0;
	if (E.call && E.step > speedFormulaL(S)) {
		E.step = 1;
		const ctemp = S.getPixelColor(0); // shift all leds left
		for (let i = 0; i < S.len - 1; i++) S.setPixelColor(i, S.getPixelColor(i + 1));
		S.setPixelColor(S.len - 1, ctemp); // wrap around
		E.aux0 = (E.aux0 + 1) & 0xFFFF;
		E.aux1 = (E.aux1 + 1) & 0xFFFF;
		if (E.aux0 == 0) E.aux0 = 0xFFFF;
		if (E.aux1 == 0) E.aux0 = 0xFFFF; // sic: C resets aux0 here
		if (E.aux0 >= width * height) E.aux0 = 0;
		if (E.aux1 >= width * height) E.aux1 = 0;
	}
	fireworks(S, E);
});

