// gradient_base, FX.cpp:1394
function gradientBase(S, E, loading) {
	if (S.len <= 1) return fbStatic(S);
	const counter = Math.imul(S.now, (S.speed >> 2) + 1) & 0xFFFF;
	let pp = ((counter * S.len) >>> 16) & 0xFFFF;
	if (E.call == 0) pp = 0;
	let val;
	const brd = S.intensity >> 1; // sic: C "1 + loading ? ix/2 : ix/4" parses as (1+loading) ? ..., so always ix/2
	const p1 = pp - S.len, p2 = pp + S.len;
	for (let i = 0; i < S.len; i++) {
		if (loading) val = Math.abs(((i > pp) ? p2 : pp) - i);
		else val = Math.min(Math.abs(pp - i), Math.min(Math.abs(p1 - i), Math.abs(p2 - i)));
		val = (brd > val) ? Math.trunc(val * 255 / brd) : 255;
		S.setPixelColor(i, color_blend(S.col[0], S.color_from_palette(i, true, S.PALETTE_SOLID_WRAP, 1), val & 0xFF));
	}
}
